/// The order guarantee a producer of rows makes about its output, which decides whether the rows it produces
/// must be kept in order downstream.
pub const DUCKDB_V2_ORDER_PRESERVATION = enum(c_int) {
    /// The rows have no meaningful order. The engine may reorder them freely, and consumers that otherwise keep
    /// insertion order, such as query results, INSERT and COPY, run in parallel without ordering them.
    ORDER_PRESERVATION_NO_ORDER = 0,
    /// The rows are produced in insertion order, which the engine keeps unless the `preserve_insertion_order`
    /// setting is disabled.
    ORDER_PRESERVATION_INSERTION_ORDER = 1,
    /// The rows are produced in an order that must be kept, as if sorted by an `ORDER BY`, even when the
    /// `preserve_insertion_order` setting is disabled.
    ORDER_PRESERVATION_FIXED_ORDER = 2,
    _,
};

