    EXPRESSION_TYPE_COMPARE_LESSTHANOREQUALTO = 29,
    /// `>=`. Two children.
    EXPRESSION_TYPE_COMPARE_GREATERTHANOREQUALTO = 30,
    /// `IN`. The first child is the value tested, the remaining children are the candidates.
    EXPRESSION_TYPE_COMPARE_IN = 35,
    /// `NOT IN`. The first child is the value tested, the remaining children are the candidates.
    EXPRESSION_TYPE_COMPARE_NOT_IN = 36,
