    RESULT_STEP_STATUS_CHUNK = 1,
    /// Stream exhausted. Sticky.
    RESULT_STEP_STATUS_FINISHED = 2,
    /// Query was interrupted. Sticky.
    RESULT_STEP_STATUS_CANCELLED = 3,
    _,
};

/// SQL statement type of a parsed statement or an executed query.
pub const DUCKDB_V2_STATEMENT_TYPE = enum(c_int) {
    STATEMENT_TYPE_INVALID = 0,
    STATEMENT_TYPE_SELECT = 1,
    STATEMENT_TYPE_INSERT = 2,
    STATEMENT_TYPE_UPDATE = 3,
    STATEMENT_TYPE_CREATE = 4,
    STATEMENT_TYPE_DELETE = 5,
    STATEMENT_TYPE_PREPARE = 6,
    STATEMENT_TYPE_EXECUTE = 7,
    STATEMENT_TYPE_ALTER = 8,
    STATEMENT_TYPE_TRANSACTION = 9,
    STATEMENT_TYPE_COPY = 10,
    STATEMENT_TYPE_ANALYZE = 11,
    STATEMENT_TYPE_VARIABLE_SET = 12,
    STATEMENT_TYPE_CREATE_FUNC = 13,
    STATEMENT_TYPE_EXPLAIN = 14,
    STATEMENT_TYPE_DROP = 15,
    STATEMENT_TYPE_EXPORT = 16,
    STATEMENT_TYPE_PRAGMA = 17,
    STATEMENT_TYPE_VACUUM = 18,
    STATEMENT_TYPE_CALL = 19,
    STATEMENT_TYPE_SET = 20,
    STATEMENT_TYPE_LOAD = 21,
    STATEMENT_TYPE_RELATION = 22,
    STATEMENT_TYPE_EXTENSION = 23,
    STATEMENT_TYPE_LOGICAL_PLAN = 24,
    STATEMENT_TYPE_ATTACH = 25,
    STATEMENT_TYPE_DETACH = 26,
    STATEMENT_TYPE_MULTI = 27,
    STATEMENT_TYPE_COPY_DATABASE = 28,
    STATEMENT_TYPE_UPDATE_EXTENSIONS = 29,
    STATEMENT_TYPE_MERGE_INTO = 30,
    STATEMENT_TYPE_CONNECT = 31,
    STATEMENT_TYPE_DISCONNECT = 32,
    STATEMENT_TYPE_EXTERNAL_RESOURCE = 33,
    STATEMENT_TYPE_PASSTHROUGH = 34,
    _,
};

/// The lexical class of a token.
pub const DUCKDB_V2_TOKEN_TYPE = enum(c_int) {
    /// Not an actual token class; out_type is set to this when `token_iterator_next` fails.
    TOKEN_TYPE_INVALID = 0,
    /// A keyword of the connection's grammar.
    TOKEN_TYPE_KEYWORD = 1,
    /// A bare or double-quoted identifier, quotes included.
    TOKEN_TYPE_IDENTIFIER = 2,
    /// A quoted or dollar-quoted string, delimiters included.
    TOKEN_TYPE_STRING_LITERAL = 3,
    /// A numeric literal.
    TOKEN_TYPE_NUMBER_LITERAL = 4,
    /// An operator or punctuation run other than the statement terminator.
    TOKEN_TYPE_OPERATOR = 5,
    /// A line or block comment, delimiters included.
    TOKEN_TYPE_COMMENT = 6,
    /// A statement-terminating semicolon.
    TOKEN_TYPE_TERMINATOR = 7,
    /// Not a token; reported by token_iterator_next once the input is exhausted, with start equal to the input length and length 0.
    TOKEN_TYPE_END_OF_INPUT = 8,
    _,
};

/// Internal representation of a vector, with FSST / SEQUENCE / SHREDDED
/// collapsed into OTHER: the view getter rejects those and requires an
/// explicit vector_flatten first. OTHER is the 0-value, so a
/// zero-initialized out-param reads as "unspecified, needs flatten" rather
/// than silently looking like FLAT.
pub const DUCKDB_V2_VECTOR_TYPE = enum(c_int) {
    /// Default for zero-init. Covers FSST / SEQUENCE / SHREDDED — call vector_flatten first.
    VECTOR_TYPE_OTHER = 0,
    /// Standard per-row storage.
    VECTOR_TYPE_FLAT = 1,
    /// A single value applies to every row in the vector.
    VECTOR_TYPE_CONSTANT = 2,
    /// Data + selection vector indirection into another vector.
    VECTOR_TYPE_DICTIONARY = 3,
    _,
};

// --- Handles -----------------------------------------------------------------------------------

/// Converts Arrow arrays into DuckDB data chunks, against one resolved ArrowSchema. Create it with
/// `arrow_importer_create`, which resolves every column's DuckDB type once, so the same importer serves any
/// number of arrays of that shape. `arrow_importer_get_schema` reports the resolved DuckDB schema.
/// `arrow_importer_append` takes an array, `arrow_importer_next_chunk` produces chunks from it, and
/// `arrow_importer_destroy` frees the importer.
///
/// The importer borrows the context it was created with and must not outlive it. One array is in flight at a
/// time, and an importer must not be used from two threads at once.
pub const duckdb_v2_arrow_importer_handle = *opaque {};

/// Converts DuckDB data chunks into Arrow arrays, for one fixed list of columns. Create it with
/// `arrow_exporter_create`, which captures the session's Arrow settings and resolves the extension types once.
/// `arrow_exporter_get_schema` reports the Arrow schema. `arrow_exporter_append` takes a chunk,
/// `arrow_exporter_next_array` produces arrays from it, and `arrow_exporter_destroy` frees the exporter.
///
/// An exporter must not be used from two threads at once.
pub const duckdb_v2_arrow_exporter_handle = *opaque {};

/// A query result that produces Arrow arrays. Works like a result, which produces data chunks. Create it with
/// `statement_execute_arrow` or `prepared_statement_execute_arrow`.
///
/// - Use it from one thread at a time.
/// - `connection_interrupt` cancels it: `arrow_result_step` reports `CANCELLED`, and
///   `arrow_result_fetch_array` and a stream's `get_next` fail.
/// - Arrays and schemas it hands out belong to the caller and stay valid after the result is destroyed.
pub const duckdb_v2_arrow_result_handle = *opaque {};

/// An owned snapshot of one base table taken at creation: where the name resolved, the table's columns, and
/// per-column catalog facts. Later DDL does not update it. Create with `connection_describe_table`, read the
/// resolved location via `table_description_get_qname`, and the columns via
/// `table_description_get_column_count` and `table_description_get_column`. Destroy via
/// `table_description_destroy`.
pub const duckdb_v2_table_description_handle = *opaque {};

/// An owned snapshot of one column of a described table: its name, type, and catalog facts. Obtain with
/// `table_description_get_column`, read with `column_description_get_name`,
/// `column_description_get_type`, `column_description_has_default` and
/// `column_description_has_generated`, and destroy with `column_description_destroy`.
pub const duckdb_v2_column_description_handle = *opaque {};

/// An opaque, owned handle to the V2 environment: the required root through
/// which instance handles are created. All instances under one environment
/// share an instance cache, so file-level conflicts — the same database
/// file opened twice — are detected across them. Destroying the
/// environment refuses with ERROR_RESOURCE_IN_USE while any instance
/// created through it is still alive; destroy those first.
pub const duckdb_v2_environment_handle = *opaque {};

/// An opaque, owned handle to a DuckDB database instance: a buffer pool, a
/// scheduler, a set of GLOBAL settings, and the databases attached to it.
/// Created empty by `instance_create`; databases are attached with
/// `instance_attach`, made the default with `instance_set_default`, and detached with
/// `instance_detach`. Always destroy via `instance_destroy`.
pub const duckdb_v2_instance_handle = *opaque {};

/// An opaque, owned handle to a DuckDB connection: a session on a database
/// instance with its own LOCAL settings and transaction state. Always
/// destroy via `connection_destroy`.
pub const duckdb_v2_connection_handle = *opaque {};

/// An opaque, owned, read-only descriptor of a single config option as seen
/// from an instance, connection, or context: its canonical name, current
/// setting, default setting, description, target scope, and aliases.
/// Returned by the *_get_option and *_get_option_by_index functions; the
/// caller always destroys it via `option_destroy`. Options are written with
/// the *_set_option functions, which take a name and a setting directly.
pub const duckdb_v2_option_handle = *opaque {};

/// Opaque detail for a failed call; destroy with `error_info_destroy`.
pub const duckdb_v2_error_info_handle = *opaque {};

/// An opaque, owned handle to a logical type. Carries a type id plus any
/// kind-specific metadata: decimal width and scale, enum dictionary, list /
/// array / struct / map / union child types, alias. A type is read-only once
/// constructed; instances arrive from a query result schema, or from one of
/// the create_type_* constructors. Always destroy via `logical_type_destroy`.
/// Borrowed strings returned by the getters are valid only until then.
pub const duckdb_v2_logical_type_handle = *opaque {};

/// An opaque, owned handle to a single SQL value: a logical type plus a
/// typed payload. Always destroy via `value_destroy`. The string returned by
/// `value_get_varchar` / `value_get_blob` is borrowed and valid only until then.
/// That holds for BIGNUM too, where what is borrowed is the opaque storage
/// form; `bignum_decode` translates it into a magnitude and a sign flag,
/// writing into a buffer the caller supplies.
pub const duckdb_v2_value_handle = *opaque {};

/// An opaque, owned handle to the streaming result of a query. Carries the
/// schema (column names and logical types), the statement type, and the
/// result type from prepare time; row data is produced incrementally by
/// stepping (`result_step`) or draining (`result_fetch_chunk`). Single consumer:
/// step from one thread at a time.
///
/// A result is a cursor on the connection's execution, not a box of data.
/// While it is live — not finished, cancelled, errored, or destroyed — the
/// connection refuses new queries with ERROR_RESOURCE_IN_USE, and the
/// query's transaction stays open, deferring version cleanup and
/// checkpointing, so drain or destroy it promptly. Side-effecting statements
/// (PRAGMA, ALTER, ...) take effect only once the result is drained. Always
/// destroy via `result_destroy`, which is safe even on a partially consumed
/// stream.
pub const duckdb_v2_result_handle = *opaque {};

/// An opaque, owned handle to a data chunk: a set of vectors of equal
/// logical length plus a cardinality (row count).
///
/// A data chunk is the main "unit of execution" in DuckDB, and the main unit of data transfer in the API.
/// It may be owned or borrowed, depending on the context.
pub const duckdb_v2_data_chunk_handle = *opaque {};

/// A borrowed handle to a vector within a data chunk, carrying a part of a column's values.
/// Vectors are always borrowed from a data chunk, and are valid only as long as their parent data chunk is alive.
pub const duckdb_v2_vector_handle = *opaque {};

/// A borrowed handle to a "arena allocator".
///
/// Bytes handed out by `arena_allocate` share the same lifetime as the arena itself.
/// `vector_get_arena` yields the arena backing the out-of-line bytes of non-inlined VARCHAR / BLOB / BIT / BIGNUM
/// values, valid until the owning vector is flattened, reallocated, or destroyed.
pub const duckdb_v2_arena_handle = *opaque {};

/// A borrowed handle to a client context: a connection seen from inside
/// DuckDB. Handed out within DuckDB-managed scopes — function bind / init /
/// exec callbacks, replacement scans, and the extension entrypoint — and
/// valid only for the duration of that scope; the caller never destroys it.
/// A context is the scope for reading (settings, the file system) and for
/// constructing values and types, not for registration: catalog entries and
/// instance-level hooks are installed through an extension or a connection.
/// A transaction is always active while a context is handed out, which is
/// what the context-scoped constructors assume.
pub const duckdb_v2_context_handle = *opaque {};

/// A column data collection represents a set of (buffer-managed) data chunks.
///
/// You can append chunks to the collection iteratively, and then scan the collection back to retrieve the chunks in order.
/// DuckDB will manage the memory for the chunks, and transparently offload chunks to disk if necessary.
/// A collection shall not be scanned while it is being appended to, and vice versa.
/// A collection shall not be appended to concurrently, but it can be scanned concurrently by multiple threads using a shared scan state and per-thread worker scan states. For concurrent appends, consider creating multiple collections and "combining" them into one collection at the end.
pub const duckdb_v2_column_data_collection_handle = *opaque {};

/// Opaque state handle for shared state across multiple threads scanning a column data collection. This is used to coordinate work distribution, track global progress, or store any other state that needs to be shared across threads during the scan of the collection.
pub const duckdb_v2_column_data_collection_shared_scan_state_handle = *opaque {};

/// Opaque state handle for local state while scanning a column data collection. This is used to track progress and any other state that needs to be maintained on a per-thread basis across calls while scanning the collection. It also keeps the buffers backing the most recently scanned chunk alive: chunks are scanned zero-copy, so a scanned chunk's data is only valid until the worker state's next scan call or its destruction.
pub const duckdb_v2_column_data_collection_worker_scan_state_handle = *opaque {};

/// Opaque state handle for appending to a column data collection. This is used to track progress and any other state that needs to be maintained across calls while appending to the collection.
pub const duckdb_v2_column_data_collection_append_state_handle = *opaque {};

/// A borrowed opaque handle to a node of a bound expression tree. Read-only and owned by the engine: valid only
/// for the duration of the callback that handed it out, and never destroyed by the caller. Child nodes borrowed
/// via `expression_get_child` share their parent's lifetime.
pub const duckdb_v2_expression_handle = *opaque {};

/// A borrowed opaque handle to a file system. Obtained from
/// `file_system_get_from_context` or `file_system_get_from_connection`, and used to open files with
/// `file_system_open`. Borrowed: the handle belongs to the context or connection it came from, is valid only
/// for as long as that is, and must not be destroyed.
pub const duckdb_v2_file_system_handle = *opaque {};

/// An owned opaque handle to the options a file is opened with. Created with `file_open_options_create`,
/// configured with `file_open_options_set_flag` and `file_open_options_set_value`, passed to
/// `file_system_open`, and destroyed with `file_open_options_destroy`. One options object can open any number
/// of files, and destroying it does not affect files already opened with it.
pub const duckdb_v2_file_open_options_handle = *opaque {};

/// An owned opaque handle to an open file, produced by `file_system_open` and destroyed with
/// `file_destroy`. Read, write, seek and sync through the `file_*` functions. Only usable while the file
/// system it was opened through is still valid.
pub const duckdb_v2_file_handle = *opaque {};

/// An owned opaque handle to a custom aggregate function being built. Created with
/// `aggregate_function_create_with_connection` or `aggregate_function_create_with_extension`, configured with
/// the setter functions (e.g. `aggregate_function_set_name`, `aggregate_function_set_update_callback`, etc.)
/// and the signature obtained via `aggregate_function_get_signature`, made available with
/// `aggregate_function_register`, and destroyed with `aggregate_function_destroy`.
pub const duckdb_v2_aggregate_function_handle = *opaque {};

/// A borrowed opaque handle to the result of an aggregate function's "bind" phase. The "bind" callback receives
/// this handle next to a `function_bind_info`, which gives access to the arguments, the user data and the
/// bind data, and can use it to set the return type of the call site being bound.
pub const duckdb_v2_aggregate_function_bind_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to an aggregate function during the state sizing "size"
/// phase. The "size" callback receives this handle and must use it to report the size of a single aggregate
/// state in bytes.
pub const duckdb_v2_aggregate_function_size_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to an aggregate function during the state
/// initialization "init" phase. The "init" callback receives this handle and can use it to access the array
/// of aggregate states it must initialize in place.
pub const duckdb_v2_aggregate_function_init_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to an aggregate function during the "update" phase.
/// The "update" callback receives this handle and can use it to access the input argument vectors, the
/// number of rows to process, and the aggregate state each row must be aggregated into.
pub const duckdb_v2_aggregate_function_update_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to an aggregate function during the "combine" phase.
/// The "combine" callback receives this handle and can use it to access the source and target aggregate
/// state arrays to merge.
pub const duckdb_v2_aggregate_function_combine_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to an aggregate function during the "finalize" phase.
/// The "finalize" callback receives this handle and can use it to access the aggregate states and the result
/// vector and offset to write their final values to.
pub const duckdb_v2_aggregate_function_finalize_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to an aggregate function during the state destruction
/// "destroy" phase. The "destroy" callback receives this handle and can use it to access the array of
/// aggregate states whose resources must be released.
pub const duckdb_v2_aggregate_function_destroy_info_handle = *opaque {};

/// An owned opaque handle to a cast function being built. Created with `cast_function_create_with_connection`
/// or `cast_function_create_with_extension`, configured with the setter functions (e.g.
/// `cast_function_set_source_type`, `cast_function_set_exec_callback`, etc.), made available with
/// `cast_function_register`, and destroyed with `cast_function_destroy`.
pub const duckdb_v2_cast_function_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a cast function during the execution "exec" phase.
/// The "exec" callback receives this handle and can use it to access the input vector, the output vector to
/// write into, the number of rows to convert, and the mode the cast is running in.
pub const duckdb_v2_cast_function_exec_info_handle = *opaque {};

/// An owned opaque handle to a custom copy function being built: an output format for `COPY ... TO`, an input
/// format for `COPY ... FROM`, or both. Created with `copy_function_create_with_connection` or
/// `copy_function_create_with_extension`, configured with the setter functions (e.g.
/// `copy_function_set_name`, `copy_to_set_batch_callback`, `copy_from_set_exec_callback`, etc.), made
/// available with `copy_function_register`, and destroyed with `copy_function_destroy`.
pub const duckdb_v2_copy_function_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the query preparation "bind" phase
/// of a `COPY ... TO` statement. The "bind" callback receives this handle and can use it to e.g. inspect the names
/// and types of the columns being written, read the statement's options and initialize some constant state.
pub const duckdb_v2_copy_to_bind_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the "batch size" phase of a
/// `COPY ... TO` statement. The "batch size" callback receives this handle and must use it to report how many rows
/// a batch should carry.
pub const duckdb_v2_copy_to_batch_size_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the per-file "init" phase of a
/// `COPY ... TO` statement. The "init" callback receives this handle and can use it to e.g. read the path of the
/// file being written and set up the state shared by every batch written to that file.
pub const duckdb_v2_copy_to_init_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the "batch" phase of a
/// `COPY ... TO` statement. The "batch" callback receives this handle and can use it to take ownership of the rows
/// of the batch and to set the prepared form of the batch handed to the "flush" callback.
pub const duckdb_v2_copy_to_batch_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the "flush" phase of a
/// `COPY ... TO` statement. The "flush" callback receives this handle and can use it to access the prepared batch
/// and write it to the output.
pub const duckdb_v2_copy_to_flush_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the per-file "finalize" phase of a
/// `COPY ... TO` statement. The "finalize" callback receives this handle and can use it to e.g. close the file
/// after every batch has been flushed to it.
pub const duckdb_v2_copy_to_finalize_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function when a `COPY ... TO` statement reports
/// statistics about the files it wrote (e.g. with `RETURN_STATS`). The "statistics" callback receives this
/// handle and uses it to report the statistics of one written file.
pub const duckdb_v2_copy_to_statistics_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the query preparation "bind" phase
/// of a `COPY ... FROM` statement. The "bind" callback receives this handle and can use it to e.g. read the path of
/// the file to read, inspect the names and types of the columns the target table expects, read the statement's
/// options, hint at the number of rows the read will produce and initialize some constant state.
pub const duckdb_v2_copy_from_bind_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the global state initialization
/// "init global" phase of a `COPY ... FROM` statement. The "init global" callback receives this handle and can use
/// it to e.g. set up the state shared by every thread reading the file, and to declare how many threads may read
/// it.
pub const duckdb_v2_copy_from_init_global_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the local state initialization
/// "init local" phase of a `COPY ... FROM` statement. The "init local" callback receives this handle and can use it
/// to e.g. set up worker-local state, typically by claiming work from the shared global state.
pub const duckdb_v2_copy_from_init_local_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the execution "exec" phase of a
/// `COPY ... FROM` statement. The "exec" callback receives this handle and can use it to e.g. access the global and
/// local state and write the next batch of rows to the output chunk.
pub const duckdb_v2_copy_from_exec_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a copy function during the "progress" phase of a
/// `COPY ... FROM` statement. The "progress" callback receives this handle and can use it to report how far the read
/// has advanced.
pub const duckdb_v2_copy_from_progress_info_handle = *opaque {};

/// A borrowed opaque handle to the call site a bind callback is binding. Every function family's bind callback
/// receives this handle next to its own bind info. It gives access to the arguments of the call, the function's
/// user data, and the bind data.
///
/// The arguments form one list in four parts, in this order: one argument per positional-only and standard
/// parameter, in declaration order; the arguments `*args` received, in call order; one argument per named-only
/// parameter, in declaration order; and the arguments `**kwargs` received, in call order. How the caller passed an
/// argument does not matter: a standard parameter passed by name is at its declared position. A parameter the call
/// omitted is present with its default value. See `function_bind_get_arg_count` for the size of each part.
pub const duckdb_v2_function_bind_info_handle = *opaque {};

/// An owned opaque handle to a replacement scan being built. Created with
/// `replacement_scan_create_with_connection`, `replacement_scan_create_with_instance` or
/// `replacement_scan_create_with_extension`, configured with `replacement_scan_set_callback` and
/// `replacement_scan_set_user_data`, made available with `replacement_scan_register`, and destroyed with
/// `replacement_scan_destroy`.
pub const duckdb_v2_replacement_scan_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a replacement scan when the binder consults it. The
/// callback receives this handle and can use it to inspect the unresolved name and to claim it by naming what to
/// read instead. Valid only for the duration of the callback; the name it hands out is owned separately and
/// outlives it.
pub const duckdb_v2_replacement_scan_info_handle = *opaque {};

/// An owned opaque handle to a custom scalar function being built. Created with
/// `scalar_function_create_with_connection` or `scalar_function_create_with_extension`, configured with the
/// setter functions (e.g. `scalar_function_set_name`, `scalar_function_set_exec_callback`, etc.) and the
/// signature obtained via `scalar_function_get_signature`, made available with `scalar_function_register`, and
/// destroyed with `scalar_function_destroy`.
pub const duckdb_v2_scalar_function_handle = *opaque {};

/// A borrowed opaque handle to the result of a scalar function's "resolve types" phase. The "resolve types"
/// callback receives this handle next to a `function_bind_info`, which gives access to the arguments and the
/// user data, and can use it to set the return type of the call site being bound.
pub const duckdb_v2_scalar_function_resolve_types_info_handle = *opaque {};

/// A borrowed opaque handle to the result of a scalar function's "bind" phase. The "bind" callback receives this
/// handle next to a `function_bind_info`, which gives access to the arguments and the user data, and can use
/// it to set the bind data of the call site being bound.
pub const duckdb_v2_scalar_function_bind_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a scalar function during the local state initialization
/// "init" phase. The "init" callback receives this handle and can use it to e.g. set up local state reusable across
/// invocations of the "exec" execution callback.
pub const duckdb_v2_scalar_function_init_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a scalar function during the execution "exec" phase.
/// The "exec" callback receives this handle and can use it to e.g. access the input argument vectors,
/// retrieve the number of rows to process, and write results to the output vector.
pub const duckdb_v2_scalar_function_exec_info_handle = *opaque {};

/// An opaque handle to a function signature. Carries the function's parameters and return type.
pub const duckdb_v2_function_signature_handle = *opaque {};

/// An owned opaque handle to a custom table function being built. Created with
/// `table_function_create_with_connection` or `table_function_create_with_extension`, configured with the
/// setter functions (e.g. `table_function_set_name`, `table_function_set_exec_callback`, etc.) and the
/// signature obtained via `table_function_get_signature`, made available with `table_function_register`, and
/// destroyed with `table_function_destroy`.
pub const duckdb_v2_table_function_handle = *opaque {};

/// A borrowed opaque handle to the result of a table function's "bind" phase. The "bind" callback receives this
/// handle next to a `function_bind_info`, which gives access to the arguments, the user data and the bind
/// data. It must use this handle to declare the columns the function returns, and can use it to hint at the
/// number of rows the scan will produce.
pub const duckdb_v2_table_function_bind_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a table function during the global state
/// initialization "init global" phase. The "init global" callback receives this handle and can use it to e.g.
/// set up the state shared by every thread scanning the function, and to declare how many threads may scan it.
pub const duckdb_v2_table_function_init_global_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a table function during the local state
/// initialization "init local" phase. The "init local" callback receives this handle and can use it to e.g.
/// set up worker-local state, typically by claiming work from the shared global state.
pub const duckdb_v2_table_function_init_local_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a table function during the execution "exec" phase.
/// The "exec" callback receives this handle and can use it to e.g. access the global and local state and write
/// the next batch of rows to the output chunk.
pub const duckdb_v2_table_function_exec_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a table function during the "progress" phase. The
/// "progress" callback receives this handle and can use it to report how far the scan has advanced.
pub const duckdb_v2_table_function_progress_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a table function during the "filter pushdown" phase of
/// query optimization. The "filter pushdown" callback receives this handle and can use it to inspect the filter
/// predicates the query applies to the function's rows, and to accept the ones it will apply itself.
pub const duckdb_v2_table_function_filter_pushdown_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a table function during the "partition data" phase.
/// The engine invokes the callback on the worker thread that just produced a batch of rows, once per batch, only
/// when a downstream operator needs to know the batch's ordering position, the values of a set of partitioning
/// columns, or both; the handle reports which of those were actually requested and receives the answer.
pub const duckdb_v2_table_function_partition_data_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a table function during the "partitioning" phase
/// of query optimization. The engine invokes the callback once per candidate `GROUP BY` column set, before
/// execution starts, to decide whether the scan can feed a partitioned aggregate directly instead of hashing.
pub const duckdb_v2_table_function_partitioning_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a table function when a scanning thread claims its
/// next batch of work. The "claim batch" callback receives this handle and can use it to claim the next part of
/// the scan from the shared global state for the thread's local state, and to report whether it claimed one.
pub const duckdb_v2_table_function_claim_batch_info_handle = *opaque {};

/// A borrowed opaque handle to the arguments supplied to a table function when the engine asks it to describe a
/// bound call. The "get bind info" callback receives this handle, and can use it to describe the call in more
/// detail than its columns: with identifiers of its columns (e.g. field ids), and with options - key-value facts
/// about what the call reads.
pub const duckdb_v2_table_function_get_bind_info_info_handle = *opaque {};

/// An owned opaque handle to a multi-file table function being built. A multi-file function wraps an already
/// registered table function that reads a single file, and adds everything that is needed to read many files
/// at once on top of it: globbing, lists of files, hive partitioning, the `filename` column, `union_by_name`
/// and the like. Created with `multi_file_function_create_with_connection` or
/// `multi_file_function_create_with_extension`, configured with the setter functions (e.g.
/// `multi_file_function_set_name`, `multi_file_function_set_single_file_function`), made available with
/// `multi_file_function_register`, and destroyed with `multi_file_function_destroy`.
pub const duckdb_v2_multi_file_function_handle = *opaque {};

/// An opaque, owned handle to the `(KEY value)` options of one
/// `instance_attach` call, as SQL `ATTACH` accepts them. Created from the
/// instance handle it will be used with via `attach_options_create`; destroy
/// it via `attach_options_destroy`.
pub const duckdb_v2_attach_options_handle = *opaque {};

/// An owned opaque handle to a custom type being built. Created with `custom_type_create_with_connection` or
/// `custom_type_create_with_extension`, configured with `custom_type_set_name` and
/// `custom_type_set_base_type`, made available with `custom_type_register`, and destroyed with
/// `custom_type_destroy`.
pub const duckdb_v2_custom_type_handle = *opaque {};

/// An owned handle to a statement bound and planned once, executable repeatedly via
/// `prepared_statement_execute`. Construct with `prepared_statement_create` and destroy with
/// `prepared_statement_destroy`. It keeps its connection's session alive, so it stays usable across executions
/// and even after the connection is disconnected.
pub const duckdb_v2_prepared_statement_handle = *opaque {};

/// An owned qualified name: an ordered path of one to three non-empty identifier parts whose last element is the
/// object name. Construct with `qname_parse` or `qname_create`, read with `qname_get_part_count` and
/// `qname_get_part`, render back to SQL with `qname_render`, compare with `qname_equals`, and destroy
/// with `qname_destroy`. Two handles are compared with `qname_equals`, never by pointer.
pub const duckdb_v2_qname_handle = *opaque {};

/// An owned, ordered list of (name, type) fields. Read with schema_get_count
/// and schema_get_field. Destroy via schema_destroy.
pub const duckdb_v2_schema_handle = *opaque {};

/// An opaque, owned handle to a single parsed SQL statement, produced by
/// statement_iterator_next. statement_execute runs it without consuming it;
/// the caller always destroys it via sql_statement_destroy.
pub const duckdb_v2_sql_statement_handle = *opaque {};

/// An opaque, owned handle to an iterator over the statements of a SQL
/// string, produced by parse_sql. Destroy it via statement_iterator_destroy;
/// statements it already yielded are independently owned and unaffected.
pub const duckdb_v2_statement_iterator_handle = *opaque {};

/// An opaque, owned handle to an iterator over the tokens of a SQL string, produced by tokenize_sql.
pub const duckdb_v2_token_iterator_handle = *opaque {};

// --- Structs -----------------------------------------------------------------------------------

/// A borrowed, length-delimited string view: `ptr` points at `len` bytes of
/// character data. The bytes are NOT guaranteed to be null-terminated and
/// may contain interior null bytes, so always honor `len` rather than
/// scanning for a terminator. The view never owns its bytes; the function
/// that produced it documents how long they live (typically "valid until the
/// owning handle is destroyed"). `{NULL, 0}` is the canonical empty view,
/// and `ptr` must not be dereferenced when `len` is 0. Not to be confused
/// with `bytes`, the transparent 16-byte *storage* format for a
/// variable-size value in a vector.
///
/// Functions take an input view as a `const str *`, which must not be
/// NULL; a NULL pointer, or a view whose `ptr` is NULL while `len` is
/// nonzero, fails with ERROR_INPUT_INVALID. Point at a `{NULL, 0}` view to
/// pass an empty string.
///
/// Text inputs, such as VARCHAR values and names, must contain valid UTF-8.
/// The caller is responsible for ensuring this; API functions do not
/// necessarily validate the input.
/// Binary inputs, such as BLOB values, do not require valid UTF-8.
pub const duckdb_v2_str = extern struct {
    ptr: ?[*]const u8,
    len: u64,
};

/// 16-byte storage for a variable-size, byte-backed value: VARCHAR, BLOB,
/// BIT, or BIGNUM. The bytes are inlined when the length is at most
/// BYTES_INLINE_LENGTH, in value.inlined.inlined; otherwise
/// value.pointer.ptr holds them and value.pointer.prefix repeats the first
/// 4. The union is transparent, so read the fields directly. VARCHAR and
/// BLOB carry no further encoding; BIT and BIGNUM do. For BIT, byte 0 is the
/// padding-bit count and bytes 1.. are the data; BIGNUM is decoded via
/// `bignum_decode`.
pub const duckdb_v2_bytes = extern struct {
    value: extern union {
        pointer: extern struct {
            length: u32,
            prefix: [4]u8,
            ptr: ?[*]u8,
        },
        inlined: extern struct {
            length: u32,
            inlined: [12]u8,
        },
    },
};

/// An opaque, owned handle to a caller-defined resource. Bundles the pointer
/// with optional callbacks that destroy and compare the resource.
pub const duckdb_v2_opaque = extern struct {
    ptr: ?*anyopaque,
    destroy: ?duckdb_v2_opaque_destroy_fn,
    equals: ?duckdb_v2_opaque_equals_fn,
};

/// The single argument to a V2 C extension entrypoint. Borrowed for the
/// duration of the call: none of its fields outlive the entrypoint, and the
/// extension destroys none of them.
pub const duckdb_v2_extension_input = extern struct {
    get_api: ?duckdb_v2_extension_get_api_fn,
    extension: duckdb_v2_extension_handle,
    context: duckdb_v2_context_handle,
    err: ?*duckdb_v2_error_info_handle,
};

pub const duckdb_v2_vector_view = extern struct {
    data: ?*const anyopaque,
    validity: ?[*]const u64,
    sel: ?[*]const duckdb_v2_sel_t,
    count: u64,
};

pub const duckdb_v2_list_entry = extern struct {
    offset: u64,
    length: u64,
};

pub const duckdb_v2_hugeint_t = extern struct {
    lower: u64,
    upper: i64,
};

pub const duckdb_v2_uhugeint_t = extern struct {
    lower: u64,
    upper: u64,
};

pub const duckdb_v2_interval_t = extern struct {
    months: i32,
    days: i32,
    micros: i64,
};

// --- Aliases -----------------------------------------------------------------------------------

/// An entry in a selection-vector.
///
/// A selection-vector is a "dictionary" represented as an array of indices (sel_t's) mapping "logical" row indices to
/// the "physical" offsets in a vectors primary data buffer. Used by "dictionary vectors" to represent a filtered or
/// "sparse" view of the vector's data.
pub const duckdb_v2_sel_t = u32;

/// VARCHAR storage. The bytes must contain valid UTF-8.
/// Read the transparent bytes fields directly.
pub const duckdb_v2_varchar_t = duckdb_v2_bytes;

/// BLOB storage. Read the transparent bytes fields directly.
pub const duckdb_v2_blob_t = duckdb_v2_bytes;

/// BIT storage. Byte 0 is the padding-bit count, bytes 1.. the data.
pub const duckdb_v2_bit_t = duckdb_v2_bytes;

/// BIGNUM storage. Decode via `bignum_decode`.
pub const duckdb_v2_bignum_t = duckdb_v2_bytes;

/// A borrowed name view with the same layout as str, marking a string
/// DuckDB treats as a SQL identifier: one matched case-insensitively.
/// Compare two identifiers case-insensitively rather than byte for byte, and
/// render one into SQL through the identifier-quoting entry point rather
/// than embedding it raw. The catalog preserves casing; some registries
/// (config settings) canonicalize to lowercase.
///
/// An identifier passed into the API must be valid UTF-8; otherwise the
/// call fails with `ERROR_INPUT_INVALID`.
pub const duckdb_v2_identifier_t = duckdb_v2_str;

// --- Callbacks ---------------------------------------------------------------------------------

/// Receives text produced by DuckDB
///
/// Invoked exactly once per producing call, with the complete text in a
/// single view.
///
/// The view is borrowed for the duration of the call only. Copy what you
/// need before returning, and do not retain `text` or `text->ptr`. The bytes are NOT guaranteed to be null-terminated.
///
/// `err` is a live error slot, never NULL. Populate it with
/// `error_info_set_code` / `error_info_set_text` to signal failure to DuckDB. Do not destroy it yourself.
///
/// The sink runs inside DuckDB's call frame: it must not throw or unwind across the boundary, and it must not
/// re-enter the API on the handle being operated on.
pub const duckdb_v2_text_sink_fn = *const fn (text: *const duckdb_v2_str, user_data: *anyopaque, err: *duckdb_v2_error_info_handle) callconv(.c) void;

/// Compares two caller-defined resources for equality.
///
/// Invoked when DuckDB needs to compare two opaque handles. The callback is
/// responsible for interpreting the pointers and comparing the underlying
/// resources. Return true if they are equal, false otherwise.
///
/// The callback runs inside DuckDB's call frame: it must not throw or unwind across the boundary, and it must not
/// re-enter the API on the handle being operated on.
pub const duckdb_v2_opaque_equals_fn = *const fn (a: *anyopaque, b: *anyopaque) callconv(.c) bool;

/// Destroys a caller-defined resource.
///
/// Invoked when DuckDB needs to destroy an opaque handle. The callback is
/// responsible for interpreting the pointer and freeing the underlying
/// resource.
///
/// The callback runs inside DuckDB's call frame: it must not throw or unwind across the boundary, and it must not
/// re-enter the API on the handle being operated on.
pub const duckdb_v2_opaque_destroy_fn = *const fn (data: *anyopaque) callconv(.c) void;

/// Hands back the function-pointer table for the API version the extension
/// was built against, or NULL if this DuckDB cannot serve it.
///
/// The extension calls it exactly once, first, through
/// DUCKDB_EXTENSION_API_INIT; nothing else in the API may be called before
/// it succeeds. A NULL return means the load has already failed and DuckDB
/// has recorded why, so the entrypoint must return without touching the
/// error slot. Statically linked extensions resolve DuckDB's symbols at link
/// time and never call it, so for those the field is NULL.
pub const duckdb_v2_extension_get_api_fn = *const fn (extension: duckdb_v2_extension_handle, version: [*]const u8) callconv(.c) ?*const anyopaque;

